"""Instants, half-open intervals, and the interval algebra the spec requires.

The spec's temporal rules are the reason this module exists rather than bare
``datetime`` use: a local wall time plus an IANA zone is not always a single
instant, and the two cases where it is not must be refused rather than guessed.
Elapsed duration is always computed in UTC; zones are retained for rendering.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import datetime, timedelta, timezone
from typing import Iterable, Sequence
from zoneinfo import ZoneInfo

__all__ = [
    "AmbiguousLocalTime",
    "Interval",
    "InvalidInterval",
    "LocalTime",
    "NonexistentLocalTime",
    "TemporalError",
    "merge",
    "subtract",
    "total_duration",
]


class TemporalError(ValueError):
    """Base class for a local time or interval that cannot be trusted."""


class NonexistentLocalTime(TemporalError):
    """The wall time never occurs in that zone (spring-forward gap)."""


class AmbiguousLocalTime(TemporalError):
    """The wall time occurs twice in that zone and no fold was supplied."""


class InvalidInterval(TemporalError):
    """An interval whose end does not strictly follow its start."""


@dataclass(frozen=True)
class LocalTime:
    """A wall time entered by staff, kept alongside the zone it was entered in.

    ``fold`` is only meaningful for a repeated wall time: 0 selects the first
    occurrence (before the clocks go back), 1 the second. Supplying it for an
    unambiguous time is harmless and ignored.
    """

    wall: str
    zone: str
    fold: int | None = None

    def __post_init__(self) -> None:
        naive = datetime.fromisoformat(self.wall)
        if naive.tzinfo is not None:
            raise TemporalError(
                f"{self.wall!r} already carries an offset; pass a bare wall time "
                "and an IANA zone so the entered local context is preserved"
            )
        tz = ZoneInfo(self.zone)

        # A gap is detected by round-tripping: for a time that never occurred,
        # zoneinfo silently shifts it, so the return trip lands somewhere else.
        probe = naive.replace(tzinfo=tz)
        if probe.astimezone(timezone.utc).astimezone(tz).replace(tzinfo=None) != naive:
            raise NonexistentLocalTime(
                f"{self.wall} does not occur in {self.zone}; clocks skip that hour"
            )

        # A repeated time has two distinct offsets. zoneinfo would default to
        # fold=0 and quietly pick one, which the spec forbids.
        if probe.utcoffset() != naive.replace(tzinfo=tz, fold=1).utcoffset():
            if self.fold is None:
                raise AmbiguousLocalTime(
                    f"{self.wall} occurs twice in {self.zone}; supply fold=0 or fold=1"
                )

        object.__setattr__(self, "_naive", naive)
        object.__setattr__(self, "_tz", tz)

    @property
    def instant(self) -> datetime:
        """The single UTC instant this wall time and zone denote."""
        naive: datetime = getattr(self, "_naive")
        tz: ZoneInfo = getattr(self, "_tz")
        return naive.replace(tzinfo=tz, fold=self.fold or 0).astimezone(timezone.utc)

    def render(self, zone: str) -> str:
        """The same instant as wall time in another zone, for display only."""
        return self.instant.astimezone(ZoneInfo(zone)).isoformat()


@dataclass(frozen=True, order=True)
class Interval:
    """A half-open ``[start, end)`` span of UTC instants.

    Half-open is what lets a 22:00 event and a 22:00 window sit adjacent
    without being reported as a conflict.
    """

    start: datetime
    end: datetime
    # Provenance for rendering and export. Excluded from comparison so an
    # interval derived by merge/subtract still equals an equivalent entered one.
    start_zone: str | None = field(default=None, compare=False)
    end_zone: str | None = field(default=None, compare=False)
    start_fold: int | None = field(default=None, compare=False)
    end_fold: int | None = field(default=None, compare=False)

    def __post_init__(self) -> None:
        for name, value in (("start", self.start), ("end", self.end)):
            if value.tzinfo is None:
                raise InvalidInterval(f"{name} must be an aware instant, got {value!r}")
        object.__setattr__(self, "start", self.start.astimezone(timezone.utc))
        object.__setattr__(self, "end", self.end.astimezone(timezone.utc))
        if self.end <= self.start:
            raise InvalidInterval(
                f"end {self.end.isoformat()} does not follow start {self.start.isoformat()}"
            )

    @classmethod
    def of(
        cls,
        start_wall: str,
        end_wall: str,
        zone: str,
        end_zone: str | None = None,
        start_fold: int | None = None,
        end_fold: int | None = None,
    ) -> "Interval":
        """Build from entered wall times. ``end_zone`` differs for travel legs."""
        arrival_zone = end_zone or zone
        return cls(
            LocalTime(start_wall, zone, start_fold).instant,
            LocalTime(end_wall, arrival_zone, end_fold).instant,
            start_zone=zone,
            end_zone=arrival_zone,
            start_fold=start_fold,
            end_fold=end_fold,
        )

    def wall(self, which: str = "start") -> str:
        """The entered wall time, rendered back in the zone it was entered in."""
        instant = self.start if which == "start" else self.end
        zone = self.start_zone if which == "start" else self.end_zone
        if zone is None:
            return instant.isoformat()
        return instant.astimezone(ZoneInfo(zone)).strftime("%Y-%m-%dT%H:%M")

    @property
    def duration(self) -> timedelta:
        return self.end - self.start

    def overlaps(self, other: "Interval") -> bool:
        return self.start < other.end and other.start < self.end

    def intersect(self, other: "Interval") -> "Interval | None":
        start = max(self.start, other.start)
        end = min(self.end, other.end)
        return Interval(start, end) if start < end else None

    def render(self, zone: str) -> str:
        tz = ZoneInfo(zone)
        return f"{self.start.astimezone(tz):%Y-%m-%d %H:%M}-{self.end.astimezone(tz):%H:%M}"


def merge(intervals: Iterable[Interval]) -> list[Interval]:
    """Union overlapping or touching intervals so shared time is counted once."""
    ordered = sorted(intervals, key=lambda i: (i.start, i.end))
    merged: list[Interval] = []
    for current in ordered:
        if merged and current.start <= merged[-1].end:
            previous = merged[-1]
            if current.end > previous.end:
                merged[-1] = Interval(previous.start, current.end)
        else:
            merged.append(current)
    return merged


def subtract(interval: Interval, blockers: Sequence[Interval]) -> list[Interval]:
    """What remains of ``interval`` once every blocker is removed."""
    remainder = [interval]
    for blocker in merge(blockers):
        next_remainder: list[Interval] = []
        for piece in remainder:
            if not piece.overlaps(blocker):
                next_remainder.append(piece)
                continue
            if piece.start < blocker.start:
                next_remainder.append(Interval(piece.start, blocker.start))
            if blocker.end < piece.end:
                next_remainder.append(Interval(blocker.end, piece.end))
        remainder = next_remainder
    return remainder


def total_duration(intervals: Iterable[Interval]) -> timedelta:
    """Summed duration after union, so overlapping windows never double count."""
    return sum((i.duration for i in merge(intervals)), timedelta())

"""Sleep opportunity, and the comparison of two scenarios' opportunity.

This implements steps 1-8 of the spec's opportunity calculation. The two rules
worth restating, because every future change will be tempted to break them:

* Free time is not opportunity. Only an entered or proposed window counts.
* Opportunity is not sleep. Nothing here estimates sleep obtained, and the
  report names its own measure so a caller cannot mistake it for one.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import timedelta

from .schedule import Event, ProtectedSleepWindow, Scenario
from .temporal import Interval, merge, subtract, total_duration

__all__ = ["Comparison", "Conflict", "EventChange", "OpportunityReport", "compare", "evaluate"]

MEASURE = "sleep opportunity"


def _hours(delta: timedelta) -> float:
    return round(delta.total_seconds() / 3600, 6)


@dataclass(frozen=True)
class Conflict:
    """An obligation that overlaps an entered sleep window.

    Reported, never resolved by deletion: the treatment stays on the schedule
    and the staff decides.
    """

    window_id: str
    event_id: str
    event_kind: str
    overlap: Interval

    def describe(self) -> str:
        return (
            f"{self.event_id} ({self.event_kind}) overlaps window {self.window_id} "
            f"for {_hours(self.overlap.duration)}h"
        )


@dataclass(frozen=True)
class OpportunityReport:
    """Opportunity within one reporting interval, with its provenance."""

    scenario: Scenario
    reporting_interval: Interval
    feasible: list[Interval]
    sources: list[ProtectedSleepWindow]
    conflicts: list[Conflict]
    target_hours: float
    target_source: str
    measure: str = MEASURE

    @property
    def hours(self) -> float:
        """Opportunity hours after union, so overlapping windows count once."""
        return _hours(total_duration(self.feasible))

    @property
    def shortfall_hours(self) -> float:
        return round(max(0.0, self.target_hours - self.hours), 6)


@dataclass(frozen=True)
class EventChange:
    event_id: str
    shift: timedelta


@dataclass(frozen=True)
class Comparison:
    baseline: OpportunityReport
    candidate: OpportunityReport
    changed_events: list[EventChange] = field(default_factory=list)
    measure: str = MEASURE

    @property
    def hours_delta(self) -> float:
        return round(self.candidate.hours - self.baseline.hours, 6)

    @property
    def resolved_conflicts(self) -> list[Conflict]:
        candidate_keys = {(c.window_id, c.event_id) for c in self.candidate.conflicts}
        return [c for c in self.baseline.conflicts if (c.window_id, c.event_id) not in candidate_keys]


def _blocked_intervals(scenario: Scenario) -> list[Interval]:
    """Mandatory obligations widened by the assumed transitions around them."""
    assumptions = scenario.assumptions
    pre_bed = assumptions.pre_bed if assumptions else timedelta()
    morning = assumptions.morning if assumptions else timedelta()
    blocked = []
    for event in scenario.obligations():
        blocked.append(
            Interval(event.interval.start - morning, event.interval.end + pre_bed)
        )
    return merge(blocked)


def evaluate(scenario: Scenario, reporting_interval: Interval) -> OpportunityReport:
    """Opportunity for ``scenario`` inside ``reporting_interval``.

    The reporting interval is supplied rather than derived so that an overnight
    total and a 24-hour total are two explicit calls, never one blended number.
    """
    if scenario.assumptions is None:
        raise ValueError("scenario needs an AssumptionSet before it can be evaluated")

    blocked = _blocked_intervals(scenario)

    conflicts: list[Conflict] = []
    feasible: list[Interval] = []
    sources: list[ProtectedSleepWindow] = []

    for window in scenario.windows:
        clipped = window.interval.intersect(reporting_interval)
        if clipped is None:
            continue
        sources.append(window)
        for event in scenario.obligations():
            overlap = clipped.intersect(event.interval)
            if overlap is not None:
                conflicts.append(
                    Conflict(window.id, event.id, event.kind, overlap)
                )
        feasible.extend(subtract(clipped, blocked))

    return OpportunityReport(
        scenario=scenario,
        reporting_interval=reporting_interval,
        feasible=merge(feasible),
        sources=sources,
        conflicts=conflicts,
        target_hours=scenario.assumptions.sleep_target_hours,
        target_source=scenario.assumptions.source,
    )


def _changed_events(baseline: Scenario, candidate: Scenario) -> list[EventChange]:
    before = {e.id: e for e in baseline.events}
    changes = []
    for event in candidate.events:
        original = before.get(event.id)
        if original and original.interval.start != event.interval.start:
            changes.append(
                EventChange(event.id, event.interval.start - original.interval.start)
            )
    return changes


def compare(baseline: OpportunityReport, candidate: OpportunityReport) -> Comparison:
    """Difference between two scenarios evaluated on common ground.

    Refuses mismatched assumptions or reporting intervals: a difference in
    opportunity is only interpretable when everything else was held equal.
    """
    if baseline.scenario.assumptions != candidate.scenario.assumptions:
        raise ValueError(
            "cannot compare scenarios built on a different assumption set; "
            f"baseline target {baseline.target_hours}h from {baseline.target_source!r}, "
            f"candidate target {candidate.target_hours}h from {candidate.target_source!r}"
        )
    if baseline.reporting_interval != candidate.reporting_interval:
        raise ValueError("cannot compare reports covering different reporting intervals")

    return Comparison(
        baseline=baseline,
        candidate=candidate,
        changed_events=_changed_events(baseline.scenario, candidate.scenario),
    )

"""Opportunity calculation from SLEEP-SCHEDULER-SPEC.md.

The rule these tests defend: free time is not opportunity. A window only counts
because staff entered it, and it only counts for the part that survives the
mandatory obligations and their transitions.
"""

from datetime import timedelta

import pytest

from sleep_scheduler.opportunity import compare, evaluate
from sleep_scheduler.schedule import (
    AssumptionSet,
    Event,
    ProtectedSleepWindow,
    Scenario,
)
from sleep_scheduler.temporal import Interval

CHICAGO = "America/Chicago"

NO_TRANSITIONS = AssumptionSet(
    sleep_target_hours=8.0,
    pre_bed_minutes=0,
    morning_minutes=0,
    source="test fixture",
)

OVERNIGHT = Interval.of("2026-09-12T18:00", "2026-09-13T12:00", CHICAGO)


def window(start: str, end: str, id: str = "w1", kind: str = "hotel"):
    return ProtectedSleepWindow(
        id=id, label=id, interval=Interval.of(start, end, CHICAGO), kind=kind
    )


def event(start: str, end: str, id: str = "e1", kind: str = "treatment"):
    return Event(
        id=id, kind=kind, title=id, interval=Interval.of(start, end, CHICAGO)
    )


def scenario(windows, events=(), assumptions=NO_TRANSITIONS):
    return Scenario(
        id="s1",
        title="test",
        display_zone=CHICAGO,
        events=list(events),
        windows=list(windows),
        assumptions=assumptions,
    )


def test_entered_window_with_no_obligations_yields_its_full_duration():
    report = evaluate(scenario([window("2026-09-12T23:30", "2026-09-13T06:00")]), OVERNIGHT)
    assert report.hours == 6.5


def test_extending_the_window_by_thirty_minutes_adds_half_an_hour():
    # Spec acceptance row: 6.5 vs 7.0 hours opportunity, +30 minutes.
    baseline = evaluate(scenario([window("2026-09-12T23:30", "2026-09-13T06:00")]), OVERNIGHT)
    candidate = evaluate(scenario([window("2026-09-12T23:30", "2026-09-13T06:30")]), OVERNIGHT)
    delta = compare(baseline, candidate)
    assert (baseline.hours, candidate.hours) == (6.5, 7.0)
    assert delta.hours_delta == 0.5


def test_report_states_opportunity_and_never_claims_sleep_obtained():
    report = evaluate(scenario([window("2026-09-12T23:30", "2026-09-13T06:00")]), OVERNIGHT)
    assert report.measure == "sleep opportunity"
    assert not hasattr(report, "sleep_hours")
    assert not hasattr(report, "predicted_sleep_hours")


def test_free_afternoon_time_is_not_counted_as_opportunity():
    # Nothing scheduled all afternoon, but no window was entered for it.
    report = evaluate(scenario([window("2026-09-12T23:30", "2026-09-13T06:00")]), OVERNIGHT)
    assert report.hours == 6.5


def test_two_overlapping_windows_are_counted_once():
    report = evaluate(
        scenario(
            [
                window("2026-09-12T22:00", "2026-09-13T04:00", id="w1"),
                window("2026-09-13T03:00", "2026-09-13T06:00", id="w2"),
            ]
        ),
        OVERNIGHT,
    )
    assert report.hours == 8.0


def test_overlapping_windows_retain_their_source_intervals():
    report = evaluate(
        scenario(
            [
                window("2026-09-12T22:00", "2026-09-13T04:00", id="w1"),
                window("2026-09-13T03:00", "2026-09-13T06:00", id="w2"),
            ]
        ),
        OVERNIGHT,
    )
    assert [w.id for w in report.sources] == ["w1", "w2"]


def test_nap_overlapping_another_opportunity_is_not_double_counted():
    report = evaluate(
        scenario(
            [
                window("2026-09-13T13:00", "2026-09-13T15:00", id="w1"),
                window("2026-09-13T14:00", "2026-09-13T15:30", id="nap", kind="nap"),
            ]
        ),
        Interval.of("2026-09-13T12:00", "2026-09-13T18:00", CHICAGO),
    )
    assert report.hours == 2.5


def test_nap_label_is_preserved_alongside_the_merged_total():
    report = evaluate(
        scenario(
            [
                window("2026-09-13T13:00", "2026-09-13T15:00", id="w1"),
                window("2026-09-13T14:00", "2026-09-13T15:30", id="nap", kind="nap"),
            ]
        ),
        Interval.of("2026-09-13T12:00", "2026-09-13T18:00", CHICAGO),
    )
    assert {w.kind for w in report.sources} == {"hotel", "nap"}


def test_treatment_overlapping_protected_sleep_is_reported_as_a_conflict():
    report = evaluate(
        scenario(
            [window("2026-09-12T23:30", "2026-09-13T06:00")],
            [event("2026-09-13T01:00", "2026-09-13T02:00", id="treatment")],
        ),
        OVERNIGHT,
    )
    assert [(c.window_id, c.event_id) for c in report.conflicts] == [("w1", "treatment")]


def test_conflicting_obligation_is_not_deleted_from_the_schedule():
    plan = scenario(
        [window("2026-09-12T23:30", "2026-09-13T06:00")],
        [event("2026-09-13T01:00", "2026-09-13T02:00", id="treatment")],
    )
    report = evaluate(plan, OVERNIGHT)
    assert [e.id for e in plan.events] == ["treatment"]
    assert [e.id for e in report.scenario.events] == ["treatment"]


def test_conflicting_obligation_reduces_the_feasible_remainder():
    report = evaluate(
        scenario(
            [window("2026-09-12T23:30", "2026-09-13T06:00")],
            [event("2026-09-13T01:00", "2026-09-13T02:00", id="treatment")],
        ),
        OVERNIGHT,
    )
    assert report.hours == 5.5


def test_morning_transition_consumes_opportunity_before_an_obligation():
    plan = scenario(
        [window("2026-09-12T23:30", "2026-09-13T08:00")],
        [event("2026-09-13T08:00", "2026-09-13T09:00", id="meeting", kind="meeting")],
        AssumptionSet(8.0, pre_bed_minutes=0, morning_minutes=45, source="test fixture"),
    )
    report = evaluate(plan, OVERNIGHT)
    assert report.hours == pytest.approx(7.75)  # 23:30 -> 07:15


def test_pre_bed_transition_delays_opportunity_after_a_late_arrival():
    plan = scenario(
        [window("2026-09-12T23:00", "2026-09-13T06:00")],
        [event("2026-09-12T22:00", "2026-09-12T23:00", id="arrival", kind="travel")],
        AssumptionSet(8.0, pre_bed_minutes=30, morning_minutes=0, source="test fixture"),
    )
    report = evaluate(plan, OVERNIGHT)
    assert report.hours == 6.5  # 23:30 -> 06:00


def test_shortfall_is_reported_against_the_assumption_set_target():
    report = evaluate(scenario([window("2026-09-12T23:30", "2026-09-13T06:00")]), OVERNIGHT)
    assert report.shortfall_hours == 1.5
    assert report.target_source == "test fixture"


def test_a_window_meeting_the_target_reports_no_shortfall():
    report = evaluate(scenario([window("2026-09-12T22:00", "2026-09-13T06:00")]), OVERNIGHT)
    assert report.shortfall_hours == 0.0


def test_opportunity_outside_the_reported_window_is_excluded():
    plan = scenario([window("2026-09-13T13:00", "2026-09-13T15:00", id="nap", kind="nap")])
    report = evaluate(plan, OVERNIGHT)
    assert report.hours == 0.0


def test_twenty_four_hour_total_is_reported_separately_from_overnight():
    plan = scenario(
        [
            window("2026-09-12T23:30", "2026-09-13T06:00", id="night"),
            window("2026-09-13T14:00", "2026-09-13T15:00", id="nap", kind="nap"),
        ]
    )
    overnight = evaluate(plan, Interval.of("2026-09-12T18:00", "2026-09-13T12:00", CHICAGO))
    day = evaluate(plan, Interval.of("2026-09-12T12:00", "2026-09-13T12:00", CHICAGO))
    full = evaluate(plan, Interval.of("2026-09-12T18:00", "2026-09-13T18:00", CHICAGO))
    assert (overnight.hours, day.hours, full.hours) == (6.5, 6.5, 7.5)


def test_compare_lists_the_events_that_changed_between_scenarios():
    baseline = evaluate(
        scenario(
            [window("2026-09-12T23:30", "2026-09-13T06:00")],
            [event("2026-09-13T06:00", "2026-09-13T07:00", id="lift", kind="training")],
        ),
        OVERNIGHT,
    )
    candidate = evaluate(
        scenario(
            [window("2026-09-12T23:30", "2026-09-13T08:00")],
            [event("2026-09-13T08:00", "2026-09-13T09:00", id="lift", kind="training")],
        ),
        OVERNIGHT,
    )
    delta = compare(baseline, candidate)
    assert [c.event_id for c in delta.changed_events] == ["lift"]
    assert delta.changed_events[0].shift == timedelta(hours=2)


def test_an_unlisted_event_kind_still_blocks_sleep():
    # Regression: a whitelist of mandatory kinds silently dropped anything not
    # on it, so a typo or a new kind quietly improved the metric.
    report = evaluate(
        scenario(
            [window("2026-09-12T23:30", "2026-09-13T06:00")],
            [event("2026-09-13T01:00", "2026-09-13T02:00", id="film", kind="film")],
        ),
        OVERNIGHT,
    )
    assert report.hours == 5.5


def test_an_unlisted_event_kind_is_reported_as_a_conflict():
    report = evaluate(
        scenario(
            [window("2026-09-12T23:30", "2026-09-13T06:00")],
            [event("2026-09-13T01:00", "2026-09-13T02:00", id="film", kind="film")],
        ),
        OVERNIGHT,
    )
    assert [c.event_id for c in report.conflicts] == ["film"]


def test_a_misspelled_kind_is_treated_as_mandatory_not_ignored():
    report = evaluate(
        scenario(
            [window("2026-09-12T23:30", "2026-09-13T06:00")],
            [event("2026-09-13T01:00", "2026-09-13T02:00", id="typo", kind="trainng")],
        ),
        OVERNIGHT,
    )
    assert report.hours == 5.5


def test_an_explicitly_optional_activity_does_not_block_sleep():
    report = evaluate(
        scenario(
            [window("2026-09-12T23:30", "2026-09-13T06:00")],
            [event("2026-09-13T01:00", "2026-09-13T02:00", id="social", kind="optional")],
        ),
        OVERNIGHT,
    )
    assert report.hours == 6.5


def test_compare_refuses_scenarios_built_on_different_assumptions():
    baseline = evaluate(scenario([window("2026-09-12T23:30", "2026-09-13T06:00")]), OVERNIGHT)
    candidate = evaluate(
        scenario(
            [window("2026-09-12T23:30", "2026-09-13T06:30")],
            assumptions=AssumptionSet(9.0, 0, 0, "different target"),
        ),
        OVERNIGHT,
    )
    with pytest.raises(ValueError, match="assumption"):
        compare(baseline, candidate)

"""JSON serialization for scenarios.

Times are stored as the wall time and IANA zone they were *entered* in, not as
a normalised UTC stamp. That is what makes the round-trip lossless in the sense
the spec asks for: a flight entered as departing 21:30 Denver and arriving
23:40 Chicago comes back the same way, not as two Chicago timestamps.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .schedule import AssumptionSet, Event, ProtectedSleepWindow, Scenario
from .temporal import Interval

__all__ = [
    "load_scenario",
    "save_scenario",
    "scenario_from_dict",
    "scenario_to_dict",
]

FORMAT_VERSION = 1


def _interval_to_dict(interval: Interval) -> dict[str, Any]:
    payload: dict[str, Any] = {
        "start": interval.wall("start"),
        "end": interval.wall("end"),
        "start_zone": interval.start_zone,
        "end_zone": interval.end_zone,
    }
    if interval.start_fold is not None:
        payload["start_fold"] = interval.start_fold
    if interval.end_fold is not None:
        payload["end_fold"] = interval.end_fold
    return payload


def _interval_from_dict(payload: dict[str, Any]) -> Interval:
    return Interval.of(
        payload["start"],
        payload["end"],
        payload["start_zone"],
        end_zone=payload.get("end_zone"),
        start_fold=payload.get("start_fold"),
        end_fold=payload.get("end_fold"),
    )


def scenario_to_dict(scenario: Scenario) -> dict[str, Any]:
    assumptions = scenario.assumptions
    return {
        "format_version": FORMAT_VERSION,
        "id": scenario.id,
        "title": scenario.title,
        "display_zone": scenario.display_zone,
        "assumptions": None
        if assumptions is None
        else {
            "sleep_target_hours": assumptions.sleep_target_hours,
            "pre_bed_minutes": assumptions.pre_bed_minutes,
            "morning_minutes": assumptions.morning_minutes,
            "source": assumptions.source,
        },
        "events": [
            {
                "id": e.id,
                "kind": e.kind,
                "title": e.title,
                "movable": e.movable,
                "location": e.location,
                "interval": _interval_to_dict(e.interval),
            }
            for e in scenario.events
        ],
        "windows": [
            {
                "id": w.id,
                "label": w.label,
                "kind": w.kind,
                "proposed": w.proposed,
                "interval": _interval_to_dict(w.interval),
            }
            for w in scenario.windows
        ],
    }


def scenario_from_dict(payload: dict[str, Any]) -> Scenario:
    version = payload.get("format_version")
    if version != FORMAT_VERSION:
        raise ValueError(
            f"unsupported scenario format_version {version!r}; expected {FORMAT_VERSION}"
        )
    raw_assumptions = payload.get("assumptions")
    return Scenario(
        id=payload["id"],
        title=payload["title"],
        display_zone=payload["display_zone"],
        events=[
            Event(
                id=e["id"],
                kind=e["kind"],
                title=e["title"],
                interval=_interval_from_dict(e["interval"]),
                movable=e.get("movable", False),
                location=e.get("location"),
            )
            for e in payload.get("events", [])
        ],
        windows=[
            ProtectedSleepWindow(
                id=w["id"],
                label=w["label"],
                interval=_interval_from_dict(w["interval"]),
                kind=w.get("kind", "hotel"),
                proposed=w.get("proposed", False),
            )
            for w in payload.get("windows", [])
        ],
        assumptions=None
        if raw_assumptions is None
        else AssumptionSet(**raw_assumptions),
    )


def save_scenario(scenario: Scenario, path: str | Path) -> None:
    Path(path).write_text(
        json.dumps(scenario_to_dict(scenario), indent=2) + "\n", encoding="utf-8"
    )


def load_scenario(path: str | Path) -> Scenario:
    return scenario_from_dict(json.loads(Path(path).read_text(encoding="utf-8")))

