foreach ($r in $roots) { if (Test-Path $r) { $repos += Get-ChildItem $r -Directory | Where-Object { Test-Path (Join-Path $_.FullName ".git") } | ForEach-Object FullName } }
$repos += "C:\Users\eric_rash\Desktop\DEV", "$HOME\.claude", "$HOME\.claude\skills", "$HOME\.claude\global-memory", "C:\Users\eric_rash\Desktop\DEV\sleep-scheduler\.claude\worktrees\calendar-core"
$count = 0; $flagged = 0
foreach ($repo in ($repos | Sort-Object -Unique)) {
  $count++
  $lines = @(git -C $repo status --porcelain 2>$null)
  $ahead = git -C $repo rev-list --count '@{u}..HEAD' 2>$null
  if ($LASTEXITCODE -ne 0) { $ahead = "no-upstream" }
  if ($lines.Count -gt 0 -or "$ahead" -ne "0") { $flagged++; "{0} | dirty={1} | ahead={2} | {3}" -f $repo, $lines.Count, $ahead, (($lines | Select-Object -First 2) -join ' ; ') }
}
"checked $count repos, flagged $flagged"

